"use strict";

var ejs = require("ejs");
var fs = require("fs");
var path = require("path");

module.exports = function(options, imports, register) {
    
    imports["connect.render"].registerEngine("ejs", createView);
    
    // JSON for a <script>: <%- JSONToJS(value) %>
    function JSONToJS(obj, indent) {
        return JSON.stringify(obj, null, indent).replace(/<\/?script|[\u2028\u2029\ud800-\uDFFF\ufeff]/ig, function(a) {
            var h =  a.charCodeAt(0).toString(16);
            return (h.length == 2 ? "\\x" : "\\u") + h + a.substr(1);
        });
    }
    // ejs 1, before scripts/install-sdk.sh updated it: also as a filter
    if (ejs.filters)
        ejs.filters.JSONToJS = JSONToJS;
    
    var helper = {
        timeSpan: function(ts) {
            var sec = 1000;
            var min = 60 * sec;
            var hour = 60 * min;

            return pad(~~(ts / hour)) + ":" + pad(~~((ts % hour) / min)) + ":" + pad(~~((ts % min) / sec));
            
            function pad(d) {
                if (d < 10)
                    return "0" + d;
                else
                    return d;
            }
        },
        timeSpanSince: function(ts) {
            return helper.timeSpan(Date.now() - ts);
        }
    };
    
    
    function createView(file, callback) {
        return callback(null, function(res, options, callback) {
            options.helper = helper;
            options.JSONToJS = JSONToJS;
            fs.readFile(file, "utf8", function(err, template) {
                if (err) return callback(err);
                
                try {
                    template = expandIncludes(file, template);
                    // ejs 3 keeps the data apart from its options (so the
                    // data can't set them); ejs 1 takes them together
                    var body = ejs.filters
                        ? ejs.render(template, Object.assign({ filename: file }, options))
                        : ejs.render(template, options, { filename: file });
                } catch (e) {
                    return callback(e);
                }
                callback(null, {
                    headers: {"Content-Type": "text/html"},
                    body: body
                });
            });
        });
    }
    
    // <% include file %> (relative to the template, as in ejs 1): ejs 3
    // only has include()
    function expandIncludes(file, template) {
        return template.replace(/<%\s*include\s+(\S+)\s*%>/g, function(match, name) {
            if (!path.extname(name)) name += ".ejs";
            var included = path.resolve(path.dirname(file), name);
            return expandIncludes(included, fs.readFileSync(included, "utf8"));
        });
    }
    
    register(null, {
        "connect.render.ejs": {
            addHelper: function(name, helper) {
                helper[name] = helper;
            }
        }
    });
};